python3 -c "
# Let's combine CM-II-2 (banks) and CM-IV-4 (nonbanking enterprises) data for 1995

# First get CM-II-2 data
with open('/app/resources/treasury_bulletin_1998_12.txt', 'r') as f:
    lines = f.readlines()

cm2_data = {}
for i in range(3471, 3600):
    line = lines[i]
    if line.startswith('|') and '---' not in line:
        parts = [p.strip() for p in line.split('|')]
        if len(parts) >= 3:
            country = parts[1].strip()
            year_1995 = parts[2].strip()

            if country and year_1995 and year_1995 != 'nan':
                if ':' not in country:
                    try:
                        val = float(year_1995.replace(',', ''))
                        cm2_data[country] = val
                    except:
                        pass
    if 'CM-II-3' in line:
        break

# Now get CM-IV-4 data  
cm4_data = {}
for i in range(4080, 4250):
    line = lines[i]
    if line.startswith('|') and '---' not in line:
        parts = [p.strip() for p in line.split('|')]
        if len(parts) >= 5:
            country = parts[1].strip()
            year_1995 = parts[4].strip()

            if country and year_1995 and year_1995 != 'nan':
                if ':' not in country:
                    try:
                        val = float(year_1995.replace(',', ''))
                        cm4_data[country] = val
                    except:
                        pass
    if 'CM-IV-5' in line:
        break

# Combine data
combined = {}
all_countries = set(cm2_data.keys()) | set(cm4_data.keys())

# Exclude territories and aggregates
territories_aggregates = {
    'Bahamas', 'Bermuda', 'British West Indies', 'Netherlands Antilles', 'Panama',
    'Total Europe', 'Total Canada', 'Total Asia', 'Total Africa', 
    'Total other countries', 'Total foreign countries',
    'International', 'European regional', 'Latin American regional',
    'Asian regional', 'African regional', 'Middle Eastern regional',
    'All other', 'Other Europe', 'Other Latin America and Caribbean', 
    'Other Asia', 'Other Africa', 'Oil-exporting countries 3', 'Oil-exporting countries 4'
}

for country in all_countries:
    if country in territories_aggregates:
        continue
    val2 = cm2_data.get(country, 0)
    val4 = cm4_data.get(country, 0)
    combined[country] = val2 + val4

# Sort by total
sorted_countries = sorted(combined.items(), key=lambda x: x[1], reverse=True)

print('Top 15 countries by TOTAL 1995 U.S. claims (banks + nonbanking enterprises):')
print('='*70)
for i, (country, val) in enumerate(sorted_countries[:15], 1):
    v2 = cm2_data.get(country, 0)
    v4 = cm4_data.get(country, 0)
    print(f'{i:2}. {country}: {val:,.0f} (Banks: {v2:,.0f}, Nonbanking: {v4:,.0f})')
"
